<?php

namespace Essential_Addons_Elementor\Pro\Traits;

use \Elementor\Controls_Manager;

if (!defined('ABSPATH')) {
    exit;
} // Exit if accessed directly

trait Login_Register_Extender
{
    public function init_login_register_hooks()
    {
        add_action('eael/login-register/before-login-form', [$this, 'render_animated_character']);
        add_filter('eael/login-register/scripts', [$this, 'add_animated_character_scripts']);
        add_action('eael/login-register/animated-character-controls', [$this, 'lr_init_animated_character_controls']);
        add_action('eael/login-register/animated-character-style-controls', [$this, 'lr_init_animated_character_style_controls']);
    }

    /**
     * Add GSAP scripts for animated character
     *
     * @param array $scripts Existing scripts
     * @return array Modified scripts array
     */
    public function add_animated_character_scripts($scripts)
    {
        // GSAP is now handled in the Enqueue trait
        return $scripts;
    }

    /**
     * Render Animated Character HTML
     *
     * @param object $widget The Login Register widget instance
     */
    public function render_animated_character($widget)
    {
        // Check if animated character is enabled
        $enable_character = $widget->get_settings_for_display('eael_animated_character_enable');
        if ('yes' !== $enable_character) {
            return;
        }

        $widget_id = $widget->get_id();
        $settings = $widget->get_settings_for_display();
        $speed = !empty($settings['eael_animated_character_speed']['size']) ? $settings['eael_animated_character_speed']['size'] : 1.0;
        $eye_tracking = !empty($settings['eael_animated_character_eye_tracking']) ? $settings['eael_animated_character_eye_tracking'] : 'no';
        $password_covering = !empty($settings['eael_animated_character_password_covering']) ? $settings['eael_animated_character_password_covering'] : 'no';
        $excited_mode = !empty($settings['eael_animated_character_excited_mode']) ? $settings['eael_animated_character_excited_mode'] : 'no';
        $shake_intensity = !empty($settings['eael_animated_character_shake_intensity']['size']) ? $settings['eael_animated_character_shake_intensity']['size'] : 1.0;

        $wrapper_classes = 'eael-animated-character-wrapper';
        ?>
        <div class="<?php echo esc_attr($wrapper_classes); ?>"
             data-widget-id="<?php echo esc_attr($widget_id); ?>"
             data-animation-speed="<?php echo esc_attr($speed); ?>"
             data-eye-tracking="<?php echo esc_attr($eye_tracking); ?>"
             data-password-covering="<?php echo esc_attr($password_covering); ?>"
             data-excited-mode="<?php echo esc_attr($excited_mode); ?>"
             data-shake-intensity="<?php echo esc_attr($shake_intensity); ?>">
            <div class="eael-animated-character eael-pickachu" id="eael-character-<?php echo esc_attr($widget_id); ?>">
                <?php $this->render_pickachu_svg(); ?>
            </div>
        </div>
        <?php
    }

