    /**
     * Add animated character content controls for Login Register widget
     *
     * @param Login_Register $lr
     */
    public function lr_init_animated_character_controls($lr)
    {
        $lr->start_controls_section(
            'eael_section_animated_character',
            [
                'label' => __('Animated Character', 'essential-addons-elementor'),
                'tab' => Controls_Manager::TAB_CONTENT,
            ]
        );

        $lr->add_control(
            'eael_animated_character_enable',
            [
                'label'        => __('Show', 'essential-addons-elementor'),
                'type'         => Controls_Manager::SWITCHER,
                'return_value' => 'yes',
                'default'      => 'no',
                'description'  => __('Enable an interactive animated character that responds to form interactions.', 'essential-addons-elementor'),
            ]
        );

        $lr->add_control(
            'eael_animated_character_speed',
            [
                'label' => __('Animation Speed', 'essential-addons-elementor'),
                'type'  => Controls_Manager::SLIDER,
                'range' => [
                    'px' => [
                        'min'  => 0.1,
                        'max'  => 3.0,
                        'step' => 0.1,
                    ],
                ],
                'default' => [
                    'size' => 1.0,
                ],
                'description' => __('Control the speed of character animations (0.1 = slow, 3.0 = fast)', 'essential-addons-elementor'),
                'condition'   => [
                    'eael_animated_character_enable' => 'yes',
                ],
            ]
        );

        $lr->add_control(
            'eael_animated_character_triggers_heading',
            [
                'label'     => __('Animation Triggers', 'essential-addons-elementor'),
                'type'      => Controls_Manager::HEADING,
                'separator' => 'before',
                'condition' => [
                    'eael_animated_character_enable' => 'yes',
                ],
            ]
        );

        $lr->add_control(
            'eael_animated_character_eye_tracking',
            [
                'label'        => __('Eye Tracking', 'essential-addons-elementor'),
                'type'         => Controls_Manager::SWITCHER,
                'label_on'     => __('Yes', 'essential-addons-elementor'),
                'label_off'    => __('No', 'essential-addons-elementor'),
                'return_value' => 'yes',
                'default'      => 'yes',
                'description'  => __('Character eyes follow cursor movement', 'essential-addons-elementor'),
                'condition'    => [
                    'eael_animated_character_enable' => 'yes',
                ],
            ]
        );

        $lr->add_control(
            'eael_animated_character_password_covering',
            [
                'label'        => __('Password Covering', 'essential-addons-elementor'),
                'type'         => Controls_Manager::SWITCHER,
                'label_on'     => __('Yes', 'essential-addons-elementor'),
                'label_off'    => __('No', 'essential-addons-elementor'),
                'return_value' => 'yes',
                'default'      => 'yes',
                'description'  => __('Character covers eyes when password field is focused', 'essential-addons-elementor'),
                'condition'    => [
                    'eael_animated_character_enable' => 'yes',
                ],
            ]
        );

        $lr->add_control(
            'eael_animated_character_excited_mode',
            [
                'label'        => __('Excited Mode', 'essential-addons-elementor'),
                'type'         => Controls_Manager::SWITCHER,
                'return_value' => 'yes',
                'default'      => 'yes',
                'description'  => __('By enabling this, Pikachu will shake its ears and tail when the user enters a correctly formatted email.', 'essential-addons-elementor'),
                'condition'    => [
                    'eael_animated_character_enable' => 'yes',
                ],
            ]
        );

        $lr->add_control(
            'eael_animated_character_shake_intensity',
            [
                'label' => __('Shake Intensity', 'essential-addons-elementor'),
                'type'  => Controls_Manager::SLIDER,
                'range' => [
                    'px' => [
                        'min'  => 0.1,
                        'max'  => 3.0,
                        'step' => 0.1,
                    ],
                ],
                'default' => [
                    'size' => 1.0,
                ],
                'description' => __('Control the shake intensity of character animations (0.1 = slow, 3.0 = fast)', 'essential-addons-elementor'),
                'condition'   => [
                    'eael_animated_character_enable' => 'yes',
                ],
            ]
        );

        $lr->end_controls_section();
    }

